/**
 * Swap every <img> that has a webp sibling over to the webp file.
 *
 * WHY A POST-BUILD SCRIPT AND NOT A SOURCE EDIT
 * The image paths live in three places that do not know about each other: the
 * catalogue records (lib/products.ts), the legacy product HTML (content/
 * products__*.json) and the homepage content (content/v2/home.ts). Rewriting
 * all three by hand leaves the next record to repeat the mistake. The webp
 * files are already generated by scripts/gen_image_variants.py on every build,
 * so the only missing step is pointing the markup at them.
 *
 * WHAT IT WILL NOT DO
 * It does not add srcset or sizes. A wrong sizes value makes a phone download a
 * larger file than it needed, and that is a worse bug than the saving is worth.
 * It only swaps the format, where a webp of the same pixel size exists.
 *
 * Idempotent: a webp src is left alone, so running the build twice changes
 * nothing the second time.
 */
import fs from 'node:fs';
import path from 'node:path';

const OUT = path.resolve('out');
const RASTER = /\.(png|jpe?g)$/i;

let filesTouched = 0;
let imgsSwapped = 0;
let bytesSaved = 0;
const seen = new Map(); // original file -> [origBytes, webpBytes], counted once
const missing = new Set();

function webpFor(absPath) {
  return absPath.replace(RASTER, '.webp');
}

function sizeOf(p) {
  try {
    return fs.statSync(p).size;
  } catch {
    return null;
  }
}

function rewriteHtml(file) {
  const html = fs.readFileSync(file, 'utf8');
  let changed = false;

  const out = html.replace(/(<img\b[^>]*?\bsrc=")([^"]+)(")/gi, (whole, before, src, after) => {
    const m = src.match(/^([^?#]*)((?:\?[^#]*)?)$/);
    if (!m) return whole;
    const pathPart = m[1];
    const query = m[2] || '';
    if (!pathPart || !RASTER.test(pathPart)) return whole;

    const rel = pathPart.replace(/^https?:\/\/[^/]+/i, '').replace(/^\//, '');
    const abs = path.join(OUT, rel);
    const wp = webpFor(abs);
    if (!fs.existsSync(wp)) {
      missing.add(pathPart);
      return whole;
    }

    const originalBytes = sizeOf(abs);
    const webpBytes = sizeOf(wp);
    if (originalBytes && webpBytes && !seen.has(abs)) {
      seen.set(abs, [originalBytes, webpBytes]);
      bytesSaved += originalBytes - webpBytes;
    }

    const newPath = pathPart.replace(RASTER, '.webp');
    changed = true;
    imgsSwapped += 1;
    return before + newPath + query + after;
  });

  if (changed) {
    fs.writeFileSync(file, out);
    filesTouched += 1;
  }
}

function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full);
    else if (entry.name.endsWith('.html')) rewriteHtml(full);
  }
}

if (!fs.existsSync(OUT)) {
  console.log('optimize_img_src: no out/ directory, nothing to do');
  process.exit(0);
}

walk(OUT);

console.log(
  `optimize_img_src: ${imgsSwapped} img src swapped to webp in ${filesTouched} html file(s), ` +
    `${(bytesSaved / 1024).toFixed(1)} KB saved across ${seen.size} distinct image(s)`,
);
if (missing.size) {
  const list = [...missing].slice(0, 6);
  console.log(`optimize_img_src: ${missing.size} image(s) had no webp sibling (left as-is): ${list.join(', ')}`);
}
